/// <summary>
/// The MobOrder class is an abstract parent class that all orders and order lines, that should be made available in the Mobile WMS, must inherit from.
/// </summary>
abstract class MobOrder implements TFMBackendIDInterface
{
    TFMDocumentMessageID    messageID;
    XMLDocument             resultXML;
    TFMPostResponseData		responseData;
    TableName               tblName;
    str                     orderId;
    str                     orderType;
    boolean                 skipRouteActivation;

    #tfm

}

