/// <returns>The result as a string.</returns>
public str postRequest(TFMRequestOrdersElement _orderElement)
{
    return '';
}

public void enrichResponseXML()
{
    XmlElement					registrationCollectorConfigurationElement;
    XmlElement					stepsElement;
    MapEnumerator				mEnum;
    TFMRegistrationCollector	collector;

    if (resultXml == null)
    {
        resultXml = new XMLDocument();
    }
    // Create the registrationCollectorConfiguration element
    registrationCollectorConfigurationElement = resultXml.createElement(TFMConstants::registrationCollectorConfiguration());

    // Create the steps element
    stepsElement = resultXml.createElement(TFMConstants::steps());
    registrationCollectorConfigurationElement.appendChild(stepsElement);
    mEnum = responseData.getCollectors().collectorMap().getEnumerator();
    while (mEnum.moveNext())
    {
        collector = mEnum.currentValue();
        collector.appendToXml(stepsElement);

    }
    resultXml.appendChild(registrationCollectorConfigurationElement);
}

public XMLDocument parmResultXML(XMLDocument _resultXML = resultXML)
{
    resultXML = _resultXML;

    if (responseData != null)
    {
        this.enrichResponseXML();
    }

    return resultXML;
}

