public static Map getAllAttributes(XmlElement _orderElement)
{
    XmlNamedNodeMap attributes = _orderElement.attributes();
    Map             attributeMap = new Map(Types::String, Types::String);
    int             i;
    for ( i = 0; i < attributes.length(); i++)
    {
        attributeMap.insert(attributes.item(i).name(),attributes.item(i).innerText());
    }
    return attributeMap;
}

