public static MobOrder constructFromTableName(TableName _tableName, TFMOrderTypes _orderType = '')
{
    MobOrder ret;
    TFMTableNameAttribute    tableNameAttribute = new TFMTableNameAttribute(_tableName,_orderType);

    if (!tableNameAttribute)
    {
        tableNameAttribute = new TFMTableNameAttribute(_tableName);
    }

    ret = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(MobOrder), tableNameAttribute);

    if (ret == null)
    {
        ret = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(MobOrder), new TFMTableNameAttribute(_tableName));
    }

    if(ret)
    {
        ret.parmTableName(_tableName);
    }

    return ret;
}

public static MobOrder constructFromBackendID(str _backendID)
{
    MobOrder  mobOrder;
    TableName tblName = subStr(_backendID,1,strScan(_backendID,'/',1,strLen(_backendID)) - 1);
    container backendIDcon = TFMHelper::strSplit(_backendID,'/').pack();
    str orderType = conLen(backendIDcon) == 7 ? conPeek(backendIDcon,7) : '';
    mobOrder = MobOrder::constructFromTableName(tblName, orderType);
    if(mobOrder)
    {
        mobOrder.parmTableName(tblName);
        mobOrder.parmOrderType(orderType);
        mobOrder.parmOrderId(MobOrder::getOrderId(_backendID));
    }
    return mobOrder;
}

/// <summary>
/// Method to get all the Order classes returning table names, that belongs to a specific area.
/// </summary>
/// <param name = "_type">A TFMOrderTypes string with the area name of Mobile WMS</param>
/// <returns>A set of table names relevant for the area.</returns>
public static Set getSubTypeTableNames(TFMOrderTypes _type)
{
    ListEnumerator          classes = new SysDictClass(classNum(TFMOrderTypeInterface)).implementedBy(true).getEnumerator();
    TFMOrderTypeInterface   orderTypeInterface;
    SysDictClass            sdc;
    MobOrder                orderCls;
    TFMTableNameAttribute   tblName;
    Set                     retSet = new Set(Types::String);
    while (classes.moveNext())
    {
        sdc = new SysDictClass(classes.current());
        if (sdc.isAbstract() || sdc.isInterface())
        {
            continue;
        }

        orderCls = sdc.makeObject();
        orderTypeInterface = orderCls as TFMOrderTypeInterface;
        if (orderTypeInterface.OrderType() != _type )
        {
            continue;
        }
        tblName = sdc.getAttribute(classStr(TFMTableNameAttribute));
        if (!tblName)
        {
            continue;
        }
        retSet.add(tblName.parmTableName()+(tblName.parmOrderType() ? ';'+tblName.parmOrderType() : ''));
    }
    return retSet;
}

public tableId lineTableId()
{
    return 0;
