public static server void addPostPromptCollectors(Map _collectors, XmlElement _parentElement, Map _additionalValues = new Map(Types::String, Types::String))
{
    MapEnumerator           mEnum = _collectors.getEnumerator();
    XmlElement              registrationCollectorConfigurationElement;
    XmlElement              stepsElement;
    XmlElement              addStep;
    str						name;

    if (_collectors == null || !_collectors.elements())
    {
        return;
    }

    // Ask the user to enter the packing slip
    // Create the registrationCollectorConfiguration element
    registrationCollectorConfigurationElement = _parentElement.ownerDocument().createElement(TFMConstants::registrationCollectorConfiguration());

    // Create the steps element
    stepsElement = _parentElement.ownerDocument().createElement(TFMConstants::steps());
    registrationCollectorConfigurationElement.appendChild(stepsElement);
    while (mEnum.moveNext())
    {
        name = TFMConstants::add();
        if ('typeAndQuantity' == mEnum.currentValue().lookup('inputType'))
        {
            name = 'typeAndQuantity';
        }
        TFMRegistrationCollector::addGenericRegistrationStep(stepsElement,name,mEnum.currentValue());
    }

    //AdditionalValues
    stepsElement = _parentElement.ownerDocument().createElement('additionalValues');
    registrationCollectorConfigurationElement.appendChild(stepsElement);
    mEnum = _additionalValues.getEnumerator();
    while (mEnum.moveNext())
    {
        addStep = _parentElement.ownerDocument().createElement('additionalValue');
        addStep.setAttribute('name',mEnum.currentKey());
        addStep.setAttribute('value',mEnum.currentValue());
        stepsElement.appendChild(addStep);
    }

    // Add the registration collector configuration to the orders element
    _parentElement.appendChild(registrationCollectorConfigurationElement);

}

public static TFMDocumentNodes ExtraInfoData(ClassName _className)
{
    ListEnumerator      lEnum           = new DictClass(className2Id(_className)).extendedBy(true).getEnumerator();
    MobOrder            typeCls;
    MapEnumerator       mEnum;

    DictClass           dc;
    TFMDocumentNodes    nodes;
    Map                 returnMap = new Map(Types::string, Types::Class);
    Map                 collectorsMap;
    MapEnumerator       collectorEnum;
    TFMDocumentNode     confignode;//  = nodes.getRoot();
    TFMDocumentNode     KeyNode;//  = nodes.makeChild(confignode,'Key');
    TFMDocumentNode     valueNode;// = nodes.makeChild(configNode,'Value');
    XmlElement          linesHeader;
    boolean             firstTime = true;
    while (lEnum.moveNext())
    {
        dc = new DictClass(lEnum.current());
        if (dc == null)
        {
            continue;
        }
        typeCls = dc.makeObject() as MobOrder;

        returnMap.insert(dc.name(),typeCls.getExtraInfoLineSteps());
    }
    mEnum = returnMap.getEnumerator();
    while (mEnum.moveNext())
    {

        collectorsMap = MobPostOrderPromptOverride::addToCollectors(mEnum.currentValue(),className2Id(mEnum.currentKey()),'',false);
        if (!collectorsMap.elements())
        {
            continue;
        }
        if (firstTime)
        {
            nodes = TFMDocumentNodes::Construct('Configuration');
        }

        confignode  = firstTime ? nodes.getRoot() : nodes.makeRootSibling('Configuration');
        KeyNode     = nodes.makeChild(confignode,'Key');
        valueNode   = nodes.makeChild(configNode,'Value');
        KeyNode.parmValue(mEnum.currentKey() +'_extraInfo');
        linesHeader = TFMGetReferenceData::createHeaderAndLine(true);
        collectorEnum = collectorsMap.getEnumerator();
        while (collectorEnum.moveNext())
        {
            TFMRegistrationCollector::addGenericRegistrationStep(linesHeader,TFMConstants::add(),collectorEnum.currentValue());
        }
        valueNode.setCDataXml(linesHeader.parentNode().xml());
        firstTime = false;
    }
    return nodes;
}
